/*
 * Host tests for the cell temperature conversion (App/bms/logic/Inc/cell_temp.h).
 *
 * Issue 62: "Sensor voltage becomes temperature through a 1 mV table
 * generated by a script from the 33 datasheet points, in 0.1 C units,
 * host-tested against those points; a reading outside 1300-2440 mV is
 * invalid."
 *
 * The points below are typed from the Enepaq Li-ion Building Block
 * datasheet, Rev E (2026-06-16), page 3, Table 5. The two thresholds are
 * from issue 25's addendum: 58 C is 1526 mV and 2 C is 2146 mV.
 */
#include "cell_temp.h"
#include "unity.h"

void setUp(void) {}
void tearDown(void) {}

static const struct {
    int      celsius;
    uint16_t mv;
} table5[] = {
    {-40, 2440}, {-35, 2420}, {-30, 2400}, {-25, 2380}, {-20, 2350}, {-15, 2320},
    {-10, 2270}, {-5, 2230},  {0, 2170},   {5, 2110},   {10, 2050},  {15, 1990},
    {20, 1920},  {25, 1860},  {30, 1800},  {35, 1740},  {40, 1680},  {45, 1630},
    {50, 1590},  {55, 1550},  {60, 1510},  {65, 1480},  {70, 1450},  {75, 1430},
    {80, 1400},  {85, 1380},  {90, 1370},  {95, 1350},  {100, 1340}, {105, 1330},
    {110, 1320}, {115, 1310}, {120, 1300},
};

static void test_every_datasheet_point_reads_its_own_temperature(void)
{
    TEST_ASSERT_EQUAL_UINT(33u, sizeof table5 / sizeof table5[0]);

    for (size_t i = 0u; i < sizeof table5 / sizeof table5[0]; i++) {
        int16_t deci = 0;
        TEST_ASSERT_TRUE(cell_temp_from_mv(table5[i].mv, &deci));
        TEST_ASSERT_EQUAL_INT16(table5[i].celsius * 10, deci);
    }
}

static void test_the_fault_thresholds_read_58_and_2_c(void)
{
    int16_t deci = 0;

    TEST_ASSERT_TRUE(cell_temp_from_mv(1526u, &deci));
    TEST_ASSERT_EQUAL_INT16(580, deci);
    TEST_ASSERT_TRUE(cell_temp_from_mv(2146u, &deci));
    TEST_ASSERT_EQUAL_INT16(20, deci);
}

static void test_between_points_is_linear_to_the_nearest_tenth(void)
{
    int16_t deci = 0;

    /* 60 C 1510 mV to 65 C 1480 mV: 1500 mV is 60 + 5 * 10 / 30 = 61.67 C. */
    TEST_ASSERT_TRUE(cell_temp_from_mv(1500u, &deci));
    TEST_ASSERT_EQUAL_INT16(617, deci);
    /* -10 C 2270 mV to -5 C 2230 mV: 2250 mV is -7.5 C. */
    TEST_ASSERT_TRUE(cell_temp_from_mv(2250u, &deci));
    TEST_ASSERT_EQUAL_INT16(-75, deci);
}

static void test_temperature_never_rises_with_voltage(void)
{
    int16_t prev = 0;

    TEST_ASSERT_TRUE(cell_temp_from_mv(CELL_TEMP_MV_MIN, &prev));
    for (uint16_t mv = CELL_TEMP_MV_MIN + 1u; mv <= CELL_TEMP_MV_MAX; mv++) {
        int16_t deci = 0;
        TEST_ASSERT_TRUE(cell_temp_from_mv(mv, &deci));
        TEST_ASSERT_TRUE(deci <= prev);
        prev = deci;
    }
}

static void test_a_reading_outside_1300_to_2440_mv_is_invalid(void)
{
    int16_t deci = 1234;

    TEST_ASSERT_FALSE(cell_temp_from_mv(1299u, &deci));
    TEST_ASSERT_FALSE(cell_temp_from_mv(2441u, &deci));
    TEST_ASSERT_FALSE(cell_temp_from_mv(0u, &deci));
    TEST_ASSERT_FALSE(cell_temp_from_mv(0xFFFFu, &deci));
    TEST_ASSERT_EQUAL_INT16(1234, deci);
}

int main(void)
{
    UNITY_BEGIN();
    RUN_TEST(test_every_datasheet_point_reads_its_own_temperature);
    RUN_TEST(test_the_fault_thresholds_read_58_and_2_c);
    RUN_TEST(test_between_points_is_linear_to_the_nearest_tenth);
    RUN_TEST(test_temperature_never_rises_with_voltage);
    RUN_TEST(test_a_reading_outside_1300_to_2440_mv_is_invalid);
    return UNITY_END();
}
